@router.get("/api/v1/wizards/cloud-deployments/{setup_id}/preview")
def preview_deployment_template(
    setup_id: str,
    wizard_store: WizardStore = Depends(get_wizard_store),
    current_user: User = Depends(get_current_user)
):
    deployment_session = wizard_store.get_session(setup_id)
    if not deployment_session or deployment_session.organization_id != current_user.organization_id:
        raise HTTPException(status_code=404, detail="Deployment setup session not found or unauthorized")
    return {
        "setup_id": setup_id,
        "target_region": deployment_session.region,
        "iam_role_arn": deployment_session.iam_role_arn,
        "cloud_access_key": deployment_session.cloud_access_key,
        "vpc_cidr": deployment_session.vpc_cidr
    }
